import{_ as t,c as a,o as i,a3 as n}from"./chunks/framework.MI-M1z4O.js";const u=JSON.parse('{"title":"SyncETA Quickstart Guide","description":"A quickstart guide to installing the SyncETA desktop application (1 minute) or running the Docker on-premises server to record and execute your first scenario.","frontmatter":{"title":"SyncETA Quickstart Guide","description":"A quickstart guide to installing the SyncETA desktop application (1 minute) or running the Docker on-premises server to record and execute your first scenario.","head":[["meta",{"name":"keywords","content":"SyncETA quickstart, getting started with test automation, desktop app download, Playwright testing, record and run, Docker deployment"}],["meta",{"property":"og:title","content":"SyncETA Quickstart Guide | Empasy"}],["meta",{"property":"og:description","content":"Run your first web regression test in 3 minutes by installing the desktop app or deploying with Docker."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/quickstart"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncETA Quickstart Guide | Empasy Docs"}],["meta",{"property":"og:description","content":"A quickstart guide to installing the SyncETA desktop application (1 minute) or running the Docker on-premises server to record and execute your first scenario."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/synceta/quickstart"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncETA Quickstart Guide | Empasy Docs"}],["meta",{"name":"twitter:description","content":"A quickstart guide to installing the SyncETA desktop application (1 minute) or running the Docker on-premises server to record and execute your first scenario."}]],"sort":30},"headers":[],"relativePath":"en/synceta/quickstart.md","filePath":"en/synceta/quickstart.md","lastUpdated":1795293539000}'),r={name:"en/synceta/quickstart.md"};function s(o,e,l,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="synceta-quickstart-guide" tabindex="-1">SyncETA Quickstart Guide <a class="header-anchor" href="#synceta-quickstart-guide" aria-label="Permalink to “SyncETA Quickstart Guide”">​</a></h1><p>There are two ways to get started with SyncETA. Choose <strong>[Method 1: Quick Desktop App Installation]</strong> if you want to try testing rapidly in a local or staging environment, or <strong>[Method 2: Docker-Based On-Premises Deployment]</strong> if you need centralized team governance and a CI/CD-integrated server.</p><hr><h2 id="method-1-quick-desktop-app-installation-recommended-start-in-1-minute" tabindex="-1">Method 1: Quick Desktop App Installation (Recommended - Start in 1 Minute) <a class="header-anchor" href="#method-1-quick-desktop-app-installation-recommended-start-in-1-minute" aria-label="Permalink to “Method 1: Quick Desktop App Installation (Recommended - Start in 1 Minute)”">​</a></h2><p>The desktop app runs immediately upon executing the OS-specific installer, without requiring separate server setup or database configuration.</p><h3 id="step-1-download-the-installer" tabindex="-1">Step 1: Download the Installer <a class="header-anchor" href="#step-1-download-the-installer" aria-label="Permalink to “Step 1: Download the Installer”">​</a></h3><p>Download the latest stable build (v0.0.44) for your operating system from the <a href="https://empasy.io/en/download_eta.html" target="_blank" rel="noreferrer">Empasy Official Download Page (empasy.io)</a>.</p><ul><li><strong>Windows</strong>: <code>SyncETA Setup 0.0.44.exe</code> (supports x64 and arm64)</li><li><strong>macOS</strong>: <code>SyncETA-0.0.44-arm64.dmg</code> (Apple Silicon M-series) or <code>SyncETA-0.0.44.dmg</code> (Intel)</li></ul><h3 id="step-2-launch-the-application" tabindex="-1">Step 2: Launch the Application <a class="header-anchor" href="#step-2-launch-the-application" aria-label="Permalink to “Step 2: Launch the Application”">​</a></h3><p>Once installation is complete, launch <strong>SyncETA</strong> from your desktop or applications list. It starts immediately in local mode without requiring separate login or external network authentication.</p><hr><h2 id="method-2-docker-compose-based-on-premises-deployment-enterprise" tabindex="-1">Method 2: Docker Compose-Based On-Premises Deployment (Enterprise) <a class="header-anchor" href="#method-2-docker-compose-based-on-premises-deployment-enterprise" aria-label="Permalink to “Method 2: Docker Compose-Based On-Premises Deployment (Enterprise)”">​</a></h2><p>Deploy the SyncETA central server and Playwright distributed execution nodes onto your internal infrastructure.</p><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone the repository and navigate to the directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/DramaticCollaboration/SyncSeries.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SyncSeries/sync-eta</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start container services in detached mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.dev.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>After the services start, open <code>http://localhost:9000</code> in your browser to access the web console.</p><hr><h2 id="hands-on-record-and-run-your-first-test-scenario" tabindex="-1">Hands-On: Record and Run Your First Test Scenario <a class="header-anchor" href="#hands-on-record-and-run-your-first-test-scenario" aria-label="Permalink to “Hands-On: Record and Run Your First Test Scenario”">​</a></h2><p>After launching the desktop app or web console, follow the 4 steps below to create and execute your first regression test.</p><h3 id="step-1-create-a-project-and-register-a-base-url" tabindex="-1">Step 1: Create a Project and Register a Base URL <a class="header-anchor" href="#step-1-create-a-project-and-register-a-base-url" aria-label="Permalink to “Step 1: Create a Project and Register a Base URL”">​</a></h3><ol><li>Click <strong>Projects</strong> in the left navigation bar.</li><li>Click the <strong>New Project</strong> button in the upper-right corner and enter a project name (e.g., <code>Commerce Main Flow</code>) and a start URL (e.g., <code>https://shop.example.com</code> or <code>http://localhost:3000</code>).</li></ol><h3 id="step-2-record-user-interactions" tabindex="-1">Step 2: Record User Interactions <a class="header-anchor" href="#step-2-record-user-interactions" aria-label="Permalink to “Step 2: Record User Interactions”">​</a></h3><ol><li>From the left menu, select <strong>Scenarios</strong> -&gt; <strong>New Scenario</strong>.</li><li>Specify the target browser (Chromium) and viewport (1920x1080), then click <strong>Start Recording</strong>.</li><li>Perform user actions in the launched browser window: <ul><li>Click the search bar and enter a search keyword</li><li>Click the search submit button</li><li>Click a specific item from the search results list</li></ul></li><li>Click <strong>Stop Recording</strong> in the recording control window. The scenario is automatically normalized into JSON/YAML format and saved.</li></ol><h3 id="step-3-add-assertions" tabindex="-1">Step 3: Add Assertions <a class="header-anchor" href="#step-3-add-assertions" aria-label="Permalink to “Step 3: Add Assertions”">​</a></h3><ol><li>Select the final step you want to verify in the saved scenario editor.</li><li>Select <strong>Add Assertion</strong> -&gt; <strong>Element Visibility Assertion</strong>, and designate the target component on the screen (e.g., the &quot;Details&quot; section or &quot;Checkout Button&quot;).</li></ol><h3 id="step-4-unattended-playwright-execution-and-self-healing-verification" tabindex="-1">Step 4: Unattended Playwright Execution and Self-Healing Verification <a class="header-anchor" href="#step-4-unattended-playwright-execution-and-self-healing-verification" aria-label="Permalink to “Step 4: Unattended Playwright Execution and Self-Healing Verification”">​</a></h3><ol><li>Click <strong>Run Scenario</strong> in the upper-right corner.</li><li>Choose an execution mode (Headless or Normal Browser) and click <strong>Run</strong>.</li><li>Once execution completes, review each step&#39;s pass/fail status, elapsed time, captured screenshots, and applied Self-Healing records on the dashboard.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="./scenario-create">Scenario Recording and Editor Guide</a> - Configuring wait conditions and recovery scripts</li><li><a href="./self-healing-and-vision">Visual Regression Verification and Selector Self-Healing</a> - Vision-LLM-based selector recovery mechanism</li><li><a href="./dataset">Dataset Management</a> - Large-scale parameterized testing using Excel</li><li><a href="./mcp-and-cicd">MCP Protocol and CI/CD Integration</a> - GitHub Actions and Jenkins pipeline integration</li></ul>`,29)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
